import pytest

def test_partition_all_inaccurate_len():
    from toolz.itertoolz import partition_all

    # Mimic tqdm behavior: an iterator with inaccurate __len__ (overestimated)
    class ProgressIterator:
        def __init__(self, iterable, total):
            self.iterable = iterable
            self.total = total

        def __iter__(self):
            return iter(self.iterable)

        def __len__(self):
            return self.total

    # Actual data: 5 items
    def make_n(n):
        for i in range(n):
            yield i

    five = make_n(5)
    # tqdm estimates total=7 (inaccurate __len__)
    progress = ProgressIterator(five, total=7)

    # Partition with n=10 (larger than both actual and reported length)
    result = list(partition_all(10, progress))

    # Should only have actual 5 items, no padding tokens
    assert result == [(0, 1, 2, 3, 4)]

    # Also test case where __len__ is underestimated (defensive)
    class UnderestimatedIterator:
        def __init__(self, iterable, total):
            self.iterable = iterable
            self.total = total

        def __iter__(self):
            return iter(self.iterable)

        def __len__(self):
            return self.total

    # Actual data: 7 items, but __len__ reports 5
    seven = make_n(7)
    underestimated = UnderestimatedIterator(seven, total=5)

    result2 = list(partition_all(10, underestimated))
    # Should have all 7 actual items, no padding
    assert result2 == [(0, 1, 2, 3, 4, 5, 6)]

